solution.python:
def missing_number(nums):
    missing = len(nums)
    for index, value in enumerate(nums):
        missing ^= index ^ value
    return missing

solution.java:
class Solution {
    public int missingNumber(int[] nums) {
        int missing = nums.length;
        for (int i = 0; i < nums.length; i++) missing ^= i ^ nums[i];
        return missing;
    }
}

